export const accountOwner='00000000-0000-4000-8000-000000000001';
export async function accountFixture(page,{provider='google',photo=true,plan='pro',routeCount=0,signature=false,insider=false}={}){await page.addInitScript(({owner,provider,photo,plan,routeCount,signature,insider})=>{
 const seed={id:owner,email:'representante@exemplo.com',user_metadata:{display_name:'Representante de teste',company_name:'Empresa de teste',...(photo?{avatar_url:'https://images.example.test/provider.png'}:{})},app_metadata:{provider,providers:[provider]},identities:[{provider}]};
 if(!localStorage.getItem('__account_user'))localStorage.setItem('__account_user',JSON.stringify(seed));window.__accountWrites=[];window.__accountStorage=[];window.__accountSignOut=[];let listeners=[];
 const load=()=>JSON.parse(localStorage.getItem('__account_user')||'null'),emit=(event,user)=>listeners.forEach(fn=>queueMicrotask(()=>fn(event,user?{user}:null)));window.__accountSwitch=value=>{localStorage.setItem('__account_user',JSON.stringify(value));emit(value?'SIGNED_IN':'SIGNED_OUT',value);};
 const fixture=window.supabase,create=fixture.createClient.bind(fixture);fixture.createClient=(...args)=>{const client=create(...args),rpc=client.rpc;client.rpc=(name,...params)=>name==='traxelo_plan_access'?Promise.resolve({data:{plan,signature,insider,beta:!signature&&!insider,portfolioCount:1,portfolioLimit:plan==='free'?1:plan==='plus'?3:null,routeLimit:plan==='free'?3:plan==='plus'?20:null,routeCount},error:null}):rpc(name,...params);client.auth={...client.auth,getSession:async()=>({data:{session:load()?{user:load()}:null},error:null}),getUser:async()=>({data:{user:load()},error:null}),onAuthStateChange:fn=>{listeners.push(fn);return{data:{subscription:{unsubscribe:()=>listeners=listeners.filter(x=>x!==fn)}}};},updateUser:async patch=>{if(window.__failAccountWrite)return{data:{},error:{message:'Synthetic update failure'}};const current=load();if(!current)return{data:{},error:{message:'no session'}};window.__accountWrites.push({data:patch.data?structuredClone(patch.data):null,email:patch.email,passwordChanged:!!patch.password});const next={...current,user_metadata:{...current.user_metadata,...patch.data},email:patch.email||current.email};localStorage.setItem('__account_user',JSON.stringify(next));emit('USER_UPDATED',next);return{data:{user:next},error:null};},reauthenticate:async()=>({data:{},error:null}),signOut:async options=>{window.__accountSignOut.push(options);if(options?.scope==='local'){localStorage.setItem('__account_user','null');emit('SIGNED_OUT',null);}return{error:null};}};
 client.storage={from:bucket=>{if(bucket!=='rotamapa-avatars')throw Error('Unexpected bucket');return{upload:async(path,blob,options)=>{const own=load()?.id;if(!path.startsWith(own+'/')||options.upsert!==false||blob.type!=='image/jpeg')return{error:{message:'denied'}};if(window.__holdAvatarUpload)await new Promise(r=>window.__releaseAvatarUpload=r);if(window.__failStorage)return{error:{message:'Synthetic storage failure'}};const data=await new Promise(resolve=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.readAsDataURL(blob);});const all=JSON.parse(localStorage.getItem('__account_files')||'{}');all[path]=data;localStorage.setItem('__account_files',JSON.stringify(all));window.__accountStorage.push({action:'upload',path,size:blob.size,type:blob.type});return{data:{path},error:null};},createSignedUrl:async path=>{if(!path.startsWith(load()?.id+'/'))return{error:{message:'denied'}};window.__accountStorage.push({action:'sign',path});return{data:{signedUrl:'https://avatars.example.test/'+encodeURIComponent(path)+'?token=synthetic'},error:null};},remove:async paths=>{const all=JSON.parse(localStorage.getItem('__account_files')||'{}');for(const path of paths){if(!path.startsWith(load()?.id+'/'))return{error:{message:'denied'}};delete all[path];window.__accountStorage.push({action:'remove',path});}localStorage.setItem('__account_files',JSON.stringify(all));return{data:[],error:null};}};}};return client;};
 },{owner:accountOwner,provider,photo,plan,routeCount,signature,insider});
 await page.route('https://images.example.test/**',r=>r.fulfill({status:200,contentType:'image/png',body:Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVQIHWP4z8DwHwAFgAI/ScLbtAAAAABJRU5ErkJggg==','base64')}));
 await page.route('https://avatars.example.test/**',async r=>{const path=decodeURIComponent(new URL(r.request().url()).pathname.slice(1)),value=await page.evaluate(path=>JSON.parse(localStorage.getItem('__account_files')||'{}')[path],path);return value?r.fulfill({status:200,contentType:'image/jpeg',body:Buffer.from(value.split(',')[1],'base64')}):r.fulfill({status:404});});
}

